import{_ as t,o,c as a,a0 as n}from"./chunks/framework.OED5XGjC.js";const m=JSON.parse('{"title":"Managed AGENTS.md blocks","description":"","frontmatter":{},"headers":[],"relativePath":"reference/agents-md-block.md","filePath":"reference/agents-md-block.md"}'),i={name:"reference/agents-md-block.md"};function s(r,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="managed-agents-md-blocks" tabindex="-1">Managed <code>AGENTS.md</code> blocks <a class="header-anchor" href="#managed-agents-md-blocks" aria-label="Permalink to &quot;Managed \`AGENTS.md\` blocks&quot;">​</a></h1><p>The <code>&lt;tool&gt;:agent-awareness</code> convention — how multiple tools each maintain a section of a repo&#39;s <code>AGENTS.md</code> without clobbering human prose or each other. Normative; <strong>myco is the reference implementation</strong> (<code>crates/myco-cli/src/agentmd.rs</code>). The sturn and kuda blocks in the sibling 9aia repos are deployed against it.</p><p>Keywords <strong>MUST</strong> / <strong>MUST NOT</strong> / <strong>SHOULD</strong> / <strong>MAY</strong> read as in RFC 2119.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p><code>AGENTS.md</code> at the repo root is agent-facing operating instructions. Each participating tool owns exactly one marker-delimited block; everything outside markers is human-owned and untouchable. A tool&#39;s init writes its block, its check verifies it, and syncs are idempotent — safe to re-run forever.</p><h2 id="the-block" tabindex="-1">The block <a class="header-anchor" href="#the-block" aria-label="Permalink to &quot;The block&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- &lt;tool&gt;:agent-awareness --&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## &lt;Tool&gt; awareness</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;tool-specific bullets&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- /&lt;tool&gt;:agent-awareness --&gt;</span></span></code></pre></div><ul><li><code>&lt;tool&gt;</code> is the implementer&#39;s canonical lowercase name (<code>myco</code>, <code>sturn</code>, <code>kuda</code>…). The marker pair is the ownership boundary — everything between them MAY be rewritten by the owning tool at any time.</li><li>Markers <strong>MUST</strong> sit on their own lines. Detection tolerates leading/trailing whitespace; canonical emission has none.</li><li>The section heading <strong>SHOULD</strong> be <code>## &lt;Tool&gt; awareness</code> — uniqueness across tools is what matters (see <em>upgrade</em> below).</li><li>Block content is tool-internal: markers are the contract, the prose inside is the tool&#39;s own business.</li></ul><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><ul><li>A tool <strong>MUST</strong> rewrite only inside its own marker pair.</li><li>All other content — human prose and foreign tools&#39; marked blocks — is opaque: preserved verbatim, never reordered, never merged, never reformatted.</li><li>Blocks coexist in any order. A new block appends at end of file; a tool <strong>MUST NOT</strong> move its own or others&#39; blocks.</li><li>A tool <strong>MUST NOT</strong> emit a second marker pair, emit markers inside foreign blocks, or leave stray markers behind.</li></ul><h2 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h2><p>The write path (<code>init</code>, <code>check --fix</code>, any rollout) applies one merge:</p><ol><li><strong>Own complete marker pair</strong> → replace the span <code>[BEGIN … END]</code> inclusive with the canonical block.</li><li><strong>No intact pair</strong> → drop stray own-markers; if the file holds the tool&#39;s claimed heading (an <em>unmarked</em> <code>## &lt;Tool&gt; awareness</code> section), replace that section through the next heading of the same-or-higher level — the upgrade path for pre-convention or hand-written content.</li><li><strong>Neither</strong> → append the canonical block at end of file.</li></ol><p>Emission rules:</p><ul><li>Exactly one blank line on each side of the block.</li><li>File ends with exactly one newline.</li><li>Bytes outside the block survive byte-for-byte — no other whitespace normalization.</li><li>Sync of already-canonical input is a <strong>no-op</strong> (no write) — this is what makes it idempotent.</li></ul><h2 id="states-check-fix" tabindex="-1">States &amp; <code>check --fix</code> <a class="header-anchor" href="#states-check-fix" aria-label="Permalink to &quot;States &amp; \`check --fix\`&quot;">​</a></h2><p>Every implementation exposes the same four-state read:</p><table tabindex="0"><thead><tr><th>state</th><th>meaning</th><th><code>check --fix</code></th></tr></thead><tbody><tr><td><code>missing</code></td><td>no <code>AGENTS.md</code></td><td>creates file + block</td></tr><tr><td><code>absent</code></td><td>file exists, nothing block-shaped</td><td>appends block</td></tr><tr><td><code>drift</code></td><td>stray markers, handwritten section, or non-canonical content</td><td>rewrites to canonical</td></tr><tr><td><code>ok</code></td><td>canonical</td><td>no finding, no write</td></tr></tbody></table><p><code>check</code> <strong>MUST</strong> surface non-<code>ok</code> as a fixable finding. Detection is a simulated sync: markers present and <code>sync(content) == content</code> (modulo the trailing newline) → <code>ok</code>.</p><h2 id="multi-tool-coexistence" tabindex="-1">Multi-tool coexistence <a class="header-anchor" href="#multi-tool-coexistence" aria-label="Permalink to &quot;Multi-tool coexistence&quot;">​</a></h2><ul><li>Foreign marked regions are opaque to <em>all</em> of a tool&#39;s logic — including its upgrade scan. When looking for its claimed heading, a tool skips headings inside other tools&#39; marker pairs.</li><li>The <code>## &lt;Tool&gt; awareness</code> naming rule is what prevents upgrade collisions: two tools scanning the same unmarked file must claim different headings.</li><li>Deployed blocks may interleave with prose arbitrarily — no tool may assume adjacency or ordering.</li></ul><h2 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h2><ul><li>Writes happen on the repo&#39;s checked-out branch (the block lives beside <code>AGENTS.md</code>, not on any tool-owned branch), committed separately from other init artifacts. myco&#39;s message: <code>chore: manage AGENTS.md agent-awareness block</code>.</li><li>Multi-repo rollout is an implementer concern (myco: <code>myco org init</code> applies the block across registered repos).</li></ul><h2 id="implementation-notes" tabindex="-1">Implementation notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to &quot;Implementation notes&quot;">​</a></h2><ul><li>myco&#39;s deployed heading is <code>## Agent awareness</code> — predates the <code>&lt;Tool&gt; awareness</code> rule; it is the one allowed exception, and its upgrade matcher is deliberately scoped to that heading so no other tool can accidentally adopt it.</li><li>myco exposes the state over the wire: <code>check --json</code> reports <code>agents_md: missing|absent|drift|ok</code> alongside the finding.</li></ul>`,25)])])}const g=t(i,[["render",s]]);export{m as __pageData,g as default};
